def get(client, clock, budget=3):
    start = clock.now()
    for attempt in range(3):
        remaining = budget - (clock.now() - start)
        if remaining <= 0:
            raise DeadlineExceeded()
        try:
            return client.get(timeout=remaining)
        except TransportError:
            if attempt == 2:
                raise
            if budget - (clock.now() - start) <= 0.1:
                raise
            clock.sleep(0.1)

